INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Trump out as President before 2027?', 'This market will resolve to “Yes” if Donald Trump resigns or is removed as President or otherwise ceases to be the President of the United States for any period of time by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to “No”. An announcement of Donald Trump''s resignation/removal before this market''s end date will immediately resolve this market to "Yes", regardless of when the announced resignation/removal goes into effect. Only permanent removal from office will qualify', 'politics', 'active', 343849.49, 4946142.7, 344349.49, 4946642.7);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will the US acquire part of Greenland in 2026?', 'This market will resolve to “Yes” if the United States acquires control of any land territory that is part of Greenland by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to “No”. Only the transfer of sovereignty, or the acquisition of primary or exclusive jurisdiction or control qualifies. 1. Transfer of Sovereignty: This will qualify if a binding agreement or legal instrument results in a defined area of Greenland coming under the formal sovereignty of the U.S. (e.g., incor', 'politics', 'active', 290177.19, 4985771.71, 290677.19, 4986271.71);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Bab el-Mandeb Strait effectively closed by September 30?', 'This market will resolve to “Yes” if IMF PortWatch publishes a 7-day moving average of transit calls (“Arrivals of Ships”) for the Bab el-Mandeb Strait less than or equal to 10 for any date between market creation and the listed date. Otherwise, this market will resolve to “No”. This market will resolve as soon as IMF PortWatch publishes a 7-day moving average of transit calls for the Bab el-Mandeb Strait equal to or below 10, or once data has been published for the listed date and no such value', 'politics', 'active', 97728, 833014.87, 98228, 833514.87);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Ethereum dip to $1,500 by December 31, 2026?', 'This market will immediately resolve to “Yes” if any Binance 1-minute candle for Ethereum (ETH/USDT) between November 24, 2025, 14:00 and December 31, 2026, 23:59 in the ET timezone has a final “Low” price equal to or lower than the price specified in the title. Otherwise, this market will resolve to “No.” The resolution source for this market is Binance, specifically the ETH/USDT “Low” prices available at: https://www.binance.com/en/trade/ETH_USDT with the chart settings on “1m” (one-minute can', 'crypto', 'active', 437082.29, 599886.38, 437582.29, 600386.38);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('2026 Balance of Power: D Senate, D House', 'This market will resolve according to the party that wins control of the United States Senate and the party that wins control of the United States House of Representatives in the 2026 United States midterm election. A party wins control of the United States Senate if it wins a majority of the chamber’s voting seats. If no party wins a majority of voting seats, the party that wins control of the chamber is the party that wins half of the voting seats and holds the Vice Presidency. If the outcome ', 'politics', 'active', 610580.59, 622915.55, 611080.59, 623415.55);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Bitcoin all time high by December 31, 2026?', 'This market will resolve to "Yes" if any Binance 1 minute candle for BTC/USDT between 16 December ''25 10:30 and 11:59PM ET on the date specified in the title has a final “High” price that is higher than any previous Binance 1 minute candle''s "High" price on any prior date. Otherwise, this market will resolve to "No". The resolution source for this market is Binance, specifically the BTC/USDT "High" prices currently available at https://www.binance.com/en/trade/BTC_USDT with “1m” and “Candles” ', 'crypto', 'active', 34731.3, 745747.41, 35231.3, 746247.41);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will the Democratic Party control the House after the 2026 Midterm elections?', 'This market will resolve according to the party that wins control of the United States House of Representatives in the 2026 United States midterm election. A party wins control of the United States House of Representatives if it wins a majority of the chamber’s voting seats. If no party wins a majority of voting seats, the chamber will be deemed controlled by the party with which the first elected Speaker of the House of the Congress that convenes after the 2026 midterm election is affiliated. T', 'politics', 'active', 2296253.19, 328036.17, 2296753.19, 328536.17);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('US x Iran diplomatic meeting by August 31, 2026?', 'On June 22, the first round of U.S.-Iran diplomatic talks in Switzerland concluded, with mediators reporting progress toward a roadmap for a final deal and follow-on technical talks expected to continue.(see: https://www.aljazeera.com/news/2026/6/22/us-iran-agree-on-roadmap-towards-final-deal-in-switzerland-talks). This market will resolve to “Yes” if the next formal senior-level round of peace talks between representatives of the United States and Iran begins by the listed date, 11:59 PM ET. Ot', 'politics', 'active', 67679.25, 319059.33, 68179.25, 319559.33);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Iran announce withdrawal from MOU negotiations by August 15?', 'On June 14, 2026, the United States and Iran announced a memorandum of understanding ending the immediate conflict and establishing a 60-day framework for negotiating a final agreement. This market will resolve to “Yes” if the Iranian government, or an authorized representative of the Iranian government, publicly and officially announces its termination of participation in the negotiation process toward the final agreement contemplated by the June 14, 2026 MOU between market creation and the spe', 'politics', 'active', 4562.7, 392193.85, 5062.7, 392693.85);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Russia capture Kostyantynivka by December 31, 2026?', 'This market will resolve to “Yes” if, according to the ISW map, Russia captures the Kostyantynivka railroad station located on Pravoberezhna vulytsia by December 31, 2026 at 11:59 PM ET. The railroad station will be considered captured if any part of the train station icon is shaded red on the ISW map (https://storymaps.arcgis.com/stories/36a7f6a6f5a9448496de641cf64bd375) by the resolution date. If the area is not shaded red by December 31, 2026, 11:59 PM ET, the market will resolve to “No”. If ', 'politics', 'active', 781102.99, 74900.29, 781602.99, 75400.29);